"""Prepare a complete synthetic request, retaining every cell/location/gene/factor and original result."""
from pathlib import Path
import argparse,json,shutil,subprocess,sys
HERE=Path(__file__).resolve().parent

def request(provider,script,inputs,outputs,out):
 return dict(schema_version=1,version='0.1.3',mode='SCRIPT',script=str(script.resolve()),provider_directory=str(provider.resolve()),inputs={n:str(p.resolve()) for n,p in inputs.items()},expected_outputs=outputs,required_symbols=['models.RegressionModel','models.Cell2location','run_colocation','utils.filtering.filter_genes'],required_distributions={'scvi-tools':'0.20.3','torch':'2.0.1+cpu','pyro-ppl':'1.8.6'},expected_return='ALL_DECLARED_ORIGINAL_CELL2LOCATION013_STAGES_RETURNED',input_provenance='Explicit synthetic raw count controls generated by the project; no recovered author data or inferred historical defaults.',analysis_population='All48 reference cells,16 spatial locations,24 genes and3 literal cell types; both NMF factor settings2/3 with2restarts each; full model states, posterior summaries, histories, save/load results, AnnData, every NMF model/matrix and all original wrapper plots retained. Short32/64 training epochs and20 posterior samples are integration controls, not convergence or biological validation.',execution_policy='ALLOW',trusted_code_policy='ALLOW',out=str(out.resolve()),limits=dict(timeout_seconds=900,maximum_files=20000,maximum_workspace_bytes=1073741824,maximum_file_bytes=536870912))

def main():
 p=argparse.ArgumentParser(description=__doc__);p.add_argument('--provider',type=Path,required=True);p.add_argument('--out',type=Path,required=True);a=p.parse_args();out=a.out.resolve();provider=a.provider.resolve()
 for protected in [provider,HERE]:
  if out.is_relative_to(protected) or protected.is_relative_to(out):raise ValueError('Output overlaps protected provider/source')
 out.mkdir(parents=True,exist_ok=False);ready=json.loads((provider/'READY.json').read_bytes());inputs=out/'inputs'
 command=[ready['python'],'-B',str(HERE/'make_fixtures.py'),'--out',str(inputs)]
 process=subprocess.run(command,capture_output=True);(out/'fixture.stdout').write_bytes(process.stdout);(out/'fixture.stderr').write_bytes(process.stderr)
 if process.returncode:raise OSError('Synthetic prerequisites unavailable; retain fixture logs and retry NEW paths')
 for n in ['OriginalControl.py','Portable.py']:shutil.copyfile(HERE/n,inputs/n)
 outputs={'workflow/'+n:v for n,v in json.loads((HERE/'example-output-profile.json').read_bytes())['expected_outputs'].items()}
 value=request(provider,HERE/'ExampleAnalysis.py',{p.name:p for p in inputs.iterdir() if p.is_file()},outputs,out/'analysis')
 (out/'request.json').write_bytes((json.dumps(value,indent=2,ensure_ascii=False)+'\n').encode('utf8'));print('READY_COMPLETE_SYNTHETIC_REQUEST_NOT_ANALYSIS',flush=True)
if __name__=='__main__':main()
